mapper.select:
SELECT o.*, p.`name` AS productName, p.`img` AS productImg, pt.`name` AS typeName, c.coupon_name as userCouponsName, u.user_name as userName FROM `gift_order` o LEFT JOIN `gift_product` p ON o.product_id = p.id LEFT JOIN `gift_product_type` pt ON o.type_id = pt.id LEFT JOIN `gift_coupon` c ON o.user_coupons_id = c.id LEFT JOIN `tb_user` u ON o.user_id = u.user_id
and o.status = #{param.status}
and o.order_no = #{param.orderNo}
and o.type_id = #{param.orderType}
and o.create_time >= #{param.startTime}
and #{param.endTime} >= o.create_time
and o.user_id = #{param.userId}
order by o.create_time desc

SELECT sum(pay_money) FROM gift_order WHERE `status` NOT IN
#{status}
AND create_time BETWEEN #{startTime} AND #{endTime}
